py.code:
class Carta(Thing):
    DIRECCIONES = ("arriba", "abajo")
    dirección = prop(one_of=DIRECCIONES)

    def voltear(self) -> None:
        self.dirección = "arriba"

    @property
    def voltear_is_enabled(self) -> bool:
        return self.dirección == "abajo"

core.describe_action(Carta, "voltear", {"title": "voltearla", "shortcuts": ["meta+T"], "enabled_when": "voltear_is_enabled", "undone_as": "Voltear carta"})
